import { MakeLogicType, actions, afterMount, connect, kea, listeners, path, reducers } from 'kea'
import { loaders } from 'kea-loaders'

import api from 'lib/api'
import { userLogic } from 'scenes/userLogic'

import { HogQLQueryResponse } from '~/queries/schema/schema-general'

import type { UserType } from '../../../../types'
import { SQL_EDITOR_PRODUCT_KEY } from '../sqlEditorLogic'

export const RECENT_QUERIES_DAYS = 7
export const RECENT_QUERIES_LIMIT = 100

export interface RecentQuery {
    query: string
    last_run_at: string
    last_exception_code: number
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface recentQueriesLogicValues {
    user: UserType | null // userLogic
    recentQueries: RecentQuery[] | null
    recentQueriesError: string | null
    recentQueriesLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface recentQueriesLogicActions {
    loadUserSuccess: (
        user: UserType | null,
        payload?:
            | {
                  resetOnFailure: boolean | undefined
              }
            | undefined
    ) => {
        payload?: {
            resetOnFailure: boolean | undefined
        }
        user: UserType | null
    } // userLogic
    loadRecentQueries: () => {
        value: true
    }
    loadRecentQueriesFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadRecentQueriesSuccess: (
        recentQueries: RecentQuery[] | null,
        payload?: {
            value: true
        }
    ) => {
        recentQueries: RecentQuery[] | null
        payload?: {
            value: true
        }
    }
}

export type recentQueriesLogicType = MakeLogicType<recentQueriesLogicValues, recentQueriesLogicActions>

export const recentQueriesLogic = kea<recentQueriesLogicType>([
    path(['scenes', 'data-warehouse', 'editor', 'recentQueriesLogic']),
    connect(() => ({
        values: [userLogic, ['user']],
        actions: [userLogic, ['loadUserSuccess']],
    })),
    actions({
        loadRecentQueries: true,
    }),
    loaders(({ values }) => ({
        recentQueries: [
            null as RecentQuery[] | null,
            {
                loadRecentQueries: async () => {
                    if (!values.user?.id) {
                        // Still unresolved rather than empty — loadUserSuccess retries below.
                        return null
                    }
                    // One editor run fans out into several ClickHouse queries under the same text,
                    // so group by the text and keep the newest run of each.
                    const response = (await api.query({
                        kind: 'HogQLQuery',
                        // Deliberately not the sql_editor product key, or this lookup lists itself.
                        tags: { productKey: 'warehouse', name: 'sql_editor_recent_queries' },
                        query: `
                            SELECT
                                query,
                                max(query_start_time) AS last_run_at,
                                argMax(exception_code, query_start_time) AS last_exception_code
                            FROM query_log
                            WHERE created_by = {user_id}
                                AND product = {product}
                                AND event_date >= today() - toIntervalDay({days})
                                AND query != ''
                            GROUP BY query
                            ORDER BY last_run_at DESC
                            LIMIT {limit}
                        `,
                        values: {
                            user_id: values.user.id,
                            product: SQL_EDITOR_PRODUCT_KEY,
                            days: RECENT_QUERIES_DAYS,
                            limit: RECENT_QUERIES_LIMIT,
                        },
                    })) as HogQLQueryResponse

                    if (!response.results || !response.columns) {
                        return []
                    }

                    const columns = response.columns as string[]
                    return response.results.map((row: any[]) => {
                        const entry: Record<string, any> = {}
                        columns.forEach((column, index) => {
                            entry[column] = row[index]
                        })
                        return entry as RecentQuery
                    })
                },
            },
        ],
    })),
    reducers({
        recentQueriesError: [
            null as string | null,
            {
                loadRecentQueries: () => null,
                loadRecentQueriesSuccess: () => null,
                loadRecentQueriesFailure: (_, { error }) => error,
            },
        ],
    }),
    listeners(({ actions }) => ({
        loadUserSuccess: () => {
            actions.loadRecentQueries()
        },
    })),
    afterMount(({ actions }) => {
        actions.loadRecentQueries()
    }),
])
